package com.hrm.gui;import com.hrm.service.AttendanceService;import javax.swing.*;import java.awt.*;public class AttendancePanel extends JPanel{private final JTable t=Ui.table(new String[]{"Mã NV","Nhân viên","Số bản ghi","Ngày công","Giờ OT"});private final JComboBox<String> y=new JComboBox<>(new String[]{"Tất cả 5 năm","2022","2023","2024","2025","2026"});private final JTextField q=new JTextField(18);public AttendancePanel(){setLayout(new BorderLayout(8,8));add(Ui.top("Chấm công & overtime - tìm theo nhân viên"),BorderLayout.NORTH);JPanel b=new JPanel(new FlowLayout(FlowLayout.LEFT));b.add(new JLabel("Tìm NV:"));b.add(q);b.add(new JLabel("Năm:"));b.add(y);add(b,BorderLayout.SOUTH);add(new JScrollPane(t),BorderLayout.CENTER);Runnable load=()->{try{Ui.fill(t,new AttendanceService().find(yearValue(),q.getText().trim()));}catch(Exception e){Ui.error(this,e);}};y.addActionListener(e->load.run());q.addActionListener(e->load.run());load.run();}private int yearValue(){String v=(String)y.getSelectedItem();return "Tất cả 5 năm".equals(v)?0:Integer.parseInt(v);}}